args.script:
const resp = await page.goto('http://127.0.0.1:5173/', { waitUntil: 'domcontentloaded' });
const title = await page.title();
const bodyText = await page.locator('body').innerText();
return {
  status: resp.status(),
  title,
  bodySnippet: bodyText.slice(0, 1000)
};

let res1, res2;
try {
  const r1 = await page.goto('http://127.0.0.1:5173/', { timeout: 4000 });
  res1 = { status: r1?.status() };
} catch(e) {
  res1 = { error: e.message };
}

try {
  const r2 = await page.goto('http://localhost:5173/', { timeout: 4000 });
  res2 = { status: r2?.status() };
} catch(e) {
  res2 = { error: e.message };
}

return { res1, res2, url: page.url() };

try {
  const resp = await page.goto('http://127.0.0.1:5173/', { timeout: 5000 });
  return { ok: true, status: resp ? resp.status() : null, url: page.url() };
} catch (e) {
  return { ok: false, error: e.message, url: page.url() };
}

// Click language dropdown
await page.locator('ref=e8').click();

// Wait for dropdown options
const menu = page.locator('role=menu').or(page.locator('.absolute, [role="listbox"]'));
// Let's capture the visible options
const bodyTextAfterClick = await page.locator('body').innerText();

return {
  menuOpen: true,
  snippet: bodyTextAfterClick.slice(0, 500)
};

const results = {};

// 1. Switch to Hindi
await page.locator('ref=e93').click();
results.hindi = {
  headline: await page.locator('h1').innerText(),
  navCrop: await page.getByRole('link', { name: /फसल|Crop/i }).first().innerText(),
  btnHero: await page.locator('main a').first().innerText()
};

// 2. Open dropdown and switch to Assamese
await page.locator('button').filter({ hasText: /हिंदी|English|অসমীয়া|Español/ }).first().click();
await page.getByRole('button', { name: /অসমীয়া/i }).click();
results.assamese = {
  headline: await page.locator('h1').innerText(),
  navCrop: await page.getByRole('link', { name: /শস্য|Crop/i }).first().innerText(),
  btnHero: await page.locator('main a').first().innerText()
};

// 3. Open dropdown and switch to Spanish
await page.locator('button').filter({ hasText: /हिंदी|English|অসমীয়া|Español/ }).first().click();
await page.getByRole('button', { name: /Español/i }).click();
results.spanish = {
  headline: await page.locator('h1').innerText(),
  navCrop: await page.getByRole('link', { name: /Cultivo|Crop/i }).first().innerText(),
  btnHero: await page.locator('main a').first().innerText()
};

// 4. Open dropdown and switch back to English
await page.locator('button').filter({ hasText: /हिंदी|English|অসমীয়া|Español/ }).first().click();
await page.getByRole('button', { name: /English/i }).click();
results.english = {
  headline: await page.locator('h1').innerText(),
  navCrop: await page.getByRole('link', { name: /Crop Recommender/i }).first().innerText(),
  btnHero: await page.locator('main a').first().innerText()
};

return results;

const results = {};

const locations = [
  "Punjab - Ludhiana District",
  "Assam - Jorhat / Upper Assam",
  "Maharashtra - Nashik Region",
  "Uttar Pradesh - Varanasi District",
  "Spain - Valencia / Mediterranean"
];

for (const loc of locations) {
  await page.locator('select').first().selectOption({ label: loc });
  // Read snapshot details
  const widgetText = await page.locator('main').locator('div').filter({ hasText: /Local Agro-Climatic Snapshot|Simulated micro-station/ }).first().innerText();
  results[loc] = widgetText;
}

return results;
